// AWI: update TiTAN brosur tahap 3 - sekali jalan (hapus setelah dipakai)
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/tfix3', array(
		'methods' => 'POST',
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function () {
			global $wpdb;
			$out = array();
			$oldv = 'https://byd-makassar.id/wp-content/uploads/2026/10/byd-ti7-v2l.webp';
			$newv = wp_get_attachment_url(10856);
			$oldh = 'https://byd-makassar.id/wp-content/uploads/2026/10/byd-ti7-hero.webp';
			$newh = wp_get_attachment_url(10847);
			foreach (array(10706, 10818, 10833, 10496, 10843) as $pid) {
				$c = get_post_field('post_content', $pid); $o = $c;
				$c = str_replace(array($oldv, $oldh), array($newv, $newh), $c);
				if ($c !== $o) { $wpdb->update($wpdb->posts, array('post_content' => $c), array('ID' => $pid)); clean_post_cache($pid); $out['p'][] = $pid; }
			}
			$t = $wpdb->prefix . 'yoast_indexable';
			if ($wpdb->get_var("SHOW TABLES LIKE '$t'") === $t) {
				$n1 = $wpdb->query($wpdb->prepare("UPDATE $t SET open_graph_image=REPLACE(open_graph_image,%s,%s), twitter_image=REPLACE(twitter_image,%s,%s), open_graph_image_id=IF(open_graph_image_id=10700,10847,open_graph_image_id), open_graph_image_meta=NULL WHERE open_graph_image LIKE %s OR twitter_image LIKE %s", $oldh, $newh, $oldh, $newh, '%byd-ti7-%', '%byd-ti7-%'));
				$out['yoast_rows'] = $n1;
				$out['left'] = $wpdb->get_var("SELECT COUNT(*) FROM $t WHERE open_graph_image LIKE '%byd-ti7-%' OR twitter_image LIKE '%byd-ti7-%'");
			}
			wp_cache_flush();
			return $out;
		},
	));
});
